(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["to"] = {"ui":{"skip":"Ō ki he meʻa ʻoku ʻi loto","back":"← Foki ki he AI-gile","lang.button":"Lea: {name}","lang.dialog":"Fili ha lea","lang.search":"Kumi lea","lang.none":"ʻIkai ha lea ʻoku fehoanaki","lang.notYet":"Kuo teʻeki liliu ʻa e {name}","theme.aria":"Fetongi ʻi he tema maama mo e tema fakapoʻuli","theme.toLight":"Fetongi ki he tema maama","theme.toDark":"Fetongi ki he tema fakapoʻuli","words.underline":"Tohi ha laine ʻi lalo ʻo e ngaahi foʻi lea ni ʻi he peesí","words.underlineHelp":"Tuku ʻa e māusi ʻi ha foʻi lea ʻoku ʻi ai hono ngaahi poini pe lomi ia ke sio ki hono ʻuhingá.","index.title":"AI-gile: hoʻo kautaha AI faʻu polokalama, ʻi he laupapa pe taha","index.description":"Ko e AI-gile ko ha laupapa kanban ia maʻa e ngaahi kautaha AI ʻoku nau tohi koti. ʻOku nau ngāue lolotonga hoʻo mohe; te ke maʻu ha fanga kiʻi haʻanga nounou ʻo e ngaahi meʻa ke ke fili, sivi mo tali.","hero.logoAlt":"Ikoni ʻo e laupapa AI-gile","hero.h1.html":"Hoʻo kautaha AI faʻu polokalama, ʻi he laupapa pe&nbsp;taha.","hero.alpha":"🐣 Pre-alpha tāpuni","hero.alphaTitle":"ʻOku teʻeki ke kakato: mālō hoʻo feinga!","hero.lede":"ʻOku nau faʻu lolotonga hoʻo mohe. Te ke ʻā ʻo maʻu ha haʻanga nounou pe taha: ngaahi fehuʻi siʻi, ngaahi meʻa siʻi ke sivi, mo ha taimane violeti ʻe taha pe ua. Lomiʻi, fakamoʻoni, pea foki ki hoʻo kofi.","dl.windows":"Polokalama Windows","dl.browser":"Fakaʻaonga ʻi hoʻo polauzā","dl.soon":"ʻOku haʻu ʻi he vave","dl.notify":"🔔 Tala mai ʻo ka ava","dl.notifySmall":"Alpha pe beta","hero.secondary":"Agile, ka ʻoku ʻikai fiemaʻu ʻe he kautaha ha kofi stand-up. (ʻOku nau fai pē stand-up.)","pitch.h2":"AI-gile ʻi he ngaahi lea ʻe lahi ʻaki hoʻo loto","pitch.lede":"Fili ha lōloa, mei he lea pe taha ki he 144. ʻOku taki taha ʻa e lōloa ko ha fakamatala makehe, naʻe tohi maʻa e lahi ko iá. Toho e slider pe ngāueʻaki e ngaahi kī ngahau.","pitch.rangeLabel":"Lōloa ʻi he ngaahi lea","pitch.dice":"🎲 paaki kehe","pitch.words.one":"lea ʻe {n}","pitch.words.other":"lea ʻe {n}","pitch.letters.one":"mataʻitohi ʻe {n}","pitch.letters.other":"mataʻitohi ʻe {n}","pitch.chars.one":"fakaʻilonga ʻe {n}","pitch.chars.other":"fakaʻilonga ʻe {n}","count.line.html.one":"kaati ʻe {n} ʻi he laupapa he taimi ni","count.line.html.other":"kaati ʻe {n} ʻi he laupapa he taimi ni","features.aria":"Ko e meʻa ʻoku ne fai","f.pile.h":"Haʻanga pe taha maʻau","f.pile.html":"Ko e <b>Maʻau</b> ʻoku ne tauhi ʻa e meʻa kotoa ʻoku tatali kiate koe, ʻi he poloseki kotoa: ngaahi fehuʻi, ngaahi meʻa ke sivi, ngaahi ngāue ʻoku faʻa fai pē ʻe ha tokotaha. ʻOku fakahā ʻe hoʻo laine ʻa e meʻa hokó mo e taimi ʻe fie maʻu.","f.sleep.h":"Ngaahi kautaha ʻoku ngāue lolotonga hoʻo mohe","f.sleep.p":"Ko e poloseki kotoa pē ʻoku ʻi ai ha taki mo ha kautaha ʻo e ngaahi ʻeiseniti AI. Fai ha fakamatala ʻi ha kaati pea ʻe ʻā ʻa e kautaha, fai e ngāue, pea ʻoatu ia mo e ngaahi sitepu ʻe lava ke muimui ai ha tokotaha ongosia.","f.tester.h":"ʻOku vakai ʻuluaki ʻe ha tokotaha sivi AI","f.tester.p":"Ki muʻa ke aʻu ha meʻa kiate koe, ʻoku muimui ʻa e tokotaha sivi ʻi he ngaahi sitepu ʻi ha kopi ʻo e polokalama pea fakahā ʻa e meʻa naʻá ne sio ki ai, mo ha screenshot. Lau fakavave ʻa e ngaahi meʻa kuo pasi pea fakamoʻoni ʻaki ha lomiʻi pe taha.","f.proof.h":"Fakamoʻoni, ʻikai ko e ngaahi talaʻofa","f.proof.p":"Ko e tuku atu kotoa ʻoku fakahā ai ʻa e meʻa kuo liliu: ngaahi faile, kehekehe, mo e ngaahi screenshot. ʻIkai fiemaʻu ke fakaava ʻa e polokalama kotoa ke sio pe kuo kakato.","f.chat.h":"Talanoa mo hoʻo ngaahi taki","f.chat.p":"Ko ha kolomu hangē ko e Discord: ko e fakaʻilonga pe taha ki he poloseki taki taha, taimane violeti maʻa e meʻa ʻoku fiemaʻu ai koe. Fekau ha fakakaukau ki ha taki; te ne liliu ia ki he ngaahi kaati mo ha palani, mo ha pātani ✅ Fai.","f.tidy.h":"ʻOku tauhi ʻe ia ʻa ia ke lelei","f.tidy.p":"Ko e ngaahi kaati fekauʻaki ʻoku fakataha ʻo hoko ko e taha, ko e ngaahi hingoa hala ʻoku fakatonutonu, pea ʻoku tauhi ʻe ha vakai token ʻa e koti ke maʻamaʻa. Siʻi ange ʻa e ngaahi meʻa ke fetongi, siʻi ange ʻa e fakakaukau.","f.private.h":"Ko hoʻo meʻa, ʻi hoʻo komipiuta","f.private.li1":"ʻOku ngāue ʻa e laupapa ʻi hoʻo komipiuta pea tali pē kiate koe.","f.private.li2":"Ko e ngaahi pōpoaki fakapulipuli ʻo e kakai ʻoku fakapulipuliʻi mei he ʻuluaki ki he ngataʻanga (end-to-end).","f.private.li3":"ʻIkai ha akauni, ʻikai ha toʻo fakaʻilonga, ʻikai ha kuki.","f.lang.h":"ʻI hoʻo lea","f.lang.p":"Lea ʻe laka hake he 120, mei he lea faka-Hōlani, faka-Uēlesi mo faka-Siapani ki he kaihaʻa tahi, Yoda mo e Klingon, mo ha fetongi vave ki he lea fakapālangi maʻa e ngaahi lea faʻu polokalama.","f.service.h":"Mei ha fakakaukau ki ha sēvesi moʻoni","f.service.p":"Kuo ke langa ha meʻa ʻaki ʻa e AI ʻoku ngāueʻaki he taimi ni ʻe he kakai? Fakaʻilongaʻi ia ko ha sēvesi pea ʻe tokoni ʻa e laupapa ke ke lele lelei ia: vakai uptime, peesi tuʻunga ki he kakai, ngaahi meʻa fakatuʻupakē mo ha lipooti, ngaahi liliu ʻoku fiemaʻu ha GO, ngaahi tatau tauhi ʻoku vakaiʻi fakaʻaho. ʻOku akoʻi ʻe he Tokoni ʻa e sitepu taki taha lolotonga hoʻo ngāue.","tl.aria":"Laine ʻo e taimi mei he talanoa ʻuluaki ki he palani","tl.h2":"Mei he talanoa ʻuluaki ki he meʻa hoko mai","tl.lede":"Ngaahi ʻaho mo e taimi moʻoni, ʻi hoʻo feituʻu taimi. Hili e ʻahó ni ko e palani pē ia, ʻikai ha ʻaho kuo talaʻofa.","tl.today":"ʻAhó ni","tl.planned":"kuo palani","tl.cards.one":"kaati ʻe {n}","tl.cards.other":"kaati ʻe {n}","join.h2":"Kau mai","join.lede":"ʻOku faʻu ʻa e AI-gile ʻe ha tangata siʻi mo ha ngaahi ʻeiseniti kātaki lahi. ʻOku fakapulipuli he taimi ni, ʻi ha alpha tāpuni mo e ngaahi kaungāmeʻa. Te ke loto ke ke feinga ʻo ka ava?","join.btn":"Lesisita hoʻo fie kau","join.small":"Te mau imeili atu, ʻikai ha toe meʻa","footer.tag":"AI-gile. ʻIkai ha toʻo fakaʻilonga, ʻikai ha kuki, ʻikai ha kofi stand-up.","footer.licence":"Laiseni pisinisi","footer.status":"Tuʻunga","footer.privacy":"Meʻa ʻoku mau tauhi","form.sending":"ʻOku fekau…","form.failed":"Naʻe ʻikai lava: feinga ʻo toe hili ha taimi.","form.offline":"Naʻe ʻikai lava ke aʻu ki he AI-gile: feinga ʻo toe hili ha taimi.","form.keep":"ʻOku mau fakaʻaongaʻi pē ia ke tali atu kiate koe, pea mau toki holoki. ʻIkai ha toʻo fakaʻilonga, ʻikai ha kuki.","form.keepLink":"Meʻa ʻoku mau tauhi","interest.title":"AI-gile: tala mai ʻo ka ava ʻa e alpha","interest.description":"Tuku mai hoʻo imeili ke ke ʻilo ʻo ka ava ʻa e alpha tāpuni pe beta ʻa e AI-gile.","interest.h1":"🔔 Tala mai ʻo ka ava","interest.lede":"ʻOku ʻi he pre-alpha tāpuni ʻa e AI-gile. Tuku mai hoʻo imeili pea te mau tohi atu taha pē, ʻo ka ʻi ai ha potu maʻau.","interest.email":"Hoʻo imeili","interest.which":"Sivi fē?","interest.alpha":"Alpha tāpuni: kei ʻuluaki, teʻeki lelei, liliu lahi","interest.beta":"Beta: lelei ange, hili ʻeni","interest.both":"Ha taha pē, ko ia ʻe hoko ʻuluaki","interest.submit":"Fakahū au ki he lisi","interest.thanks":"Mālō! ʻOku ʻi he lisi koe.","licence.title":"AI-gile: laiseni pisinisi","licence.description":"ʻOkú ke fakaʻaongaʻi ʻa e AI-gile ʻi hoʻo pisinisi? Kole ha laiseni pisinisi ʻikai ha totongi.","licence.h1":"📜 Laiseni pisinisi","licence.lede":"ʻOkú ke fakaʻaongaʻi ʻa e AI-gile ʻi he ngāue? Tala mai pe ko hai koe mo e meʻa ʻokú ke faí. Kapau ʻoku fai ha lelei, ʻikai ha totongi ʻa e laiseni.","licence.company":"Kautaha","licence.website":"Uepisaiti","licence.what":"Meʻa ʻokú ke faí","licence.how":"Founga ʻoku tokoni ai ki he māmani","licence.email":"Imeili","licence.submit":"Kole","licence.thanks":"Mālō! Te mau tali ʻaki e imeili.","status.title":"Tuʻunga ʻo e AI-gile","status.h1":"Tuʻunga ʻo e AI-gile","status.quiet":"Longolongo kotoa","status.intro":"ʻOku ngāue ʻa e AI-gile he taimí ni? ʻOku sivi ʻe he peesi ni ʻa e uepisaiti, vahevahe laupapa, telefoni mo e download ʻi he miniti ʻe 5 kotoa pē.","status.up":"ʻOku ngāue (naʻe tali ʻi he {ms} ms)","status.slow":"Naʻe ʻikai tali ʻi he sivi fakamuimuí, ʻoku toe feinga","status.down":"Hinga: naʻe ʻikai tali ʻi he sivi fakamuimui ʻe uá","status.svc.web":"Uepisaiti","status.svc.web.offers":"Ko e saiti ni: ko e hā ʻa e AI-gile, mo e foomu fie kau","status.svc.boards":"Vahevahe laupapa","status.svc.boards.offers":"Ngaahi laupapa maʻa e kakai kotoa, ngaahi pōpoaki ʻi he vahaʻa ʻo e ngaahi kaungāmeʻa mo e ngaahi fakaafe","status.svc.calls":"Telefoni","status.svc.calls.offers":"Leʻo, vitiō mo e vahevahe sikilini ʻi he AI-gile","status.svc.download":"Download","status.svc.download.offers":"Ko e polokalama fokotuʻu ki he Windows mo e ngaahi link fakaafe","status.checking":"ʻOku sivi…","status.offline":"ʻOku ʻikai lava ke aʻu ki he tokoni tuʻunga he taimi ni (ʻoku toe feinga)","status.updated":"kuo fakafoʻou {ago}","status.justNow":"he taimi pē ni","status.min":"miniti ʻe {n} kuo hili","status.hours":"houa ʻe {n} kuo hili","status.days":"ʻaho ʻe {n} kuo hili","privacy.title":"AI-gile: meʻa ʻoku mau tauhi","privacy.h1":"Meʻa ʻoku mau tauhi","privacy.lede":"Fakanounou: ko e meʻa pē ʻokú ke fekau mai, pea ʻikai fuoloa.","privacy.only":"Ko e meʻa pē ʻokú ke fekau mai: ko e meʻa ʻokú ke tohi ʻi ha foomu, hangē ko hoʻo imeilí. ʻIkai ha toe meʻa kehe fekauʻaki mo koe.","privacy.sealed":"ʻOku silaʻi ia koeʻuhi ke ʻoua naʻa lava ʻe homau sēvá ʻo lau: ʻi hoʻo browser kimuʻa pea ʻalu (ʻi ha browser motuʻa, ʻi he taimi pē ʻoku aʻu mai ai). Ko homau laupapá pē ʻe lava ʻo fakaava ia.","privacy.server":"ʻOku holoki ia mei he sēvá ʻi he taimi pē ʻoku aʻu ai ki homau laupapá. Ko ha meʻa ʻoku kei ʻi ai hili ha ʻaho ʻe 30 ʻoku holoki pē ia.","privacy.board":"ʻOku mau tauhi ia ʻi homau laupapá kae ʻoua kuo mau tali atu kiate koe, pea mau toki holoki foki ia ʻi ai.","privacy.none":"ʻIkai ha toʻo fakaʻilonga, ʻikai ha kuki, ʻikai ha fakatotolo fakafika.","privacy.local":"Ko hoʻo leá mo hoʻo fili ʻo e maama pe fakapoʻulí ʻoku nofo pē ʻi hoʻo browser. ʻOku ʻikai teitei fekau mai ia kiate kimautolu.","privacy.ask":"Fie holoki vave ange? Tali mai ki heʻemau imeilí ʻo tala mai.","live.h2":"Sio ki heʻene langa, moʻui","live.caption":"Kuo fufū e kaati kotoa: ke ke sio ki he fōtunga ʻo e ngāue, ʻikai ko e ngaahi lea.","live.watching.one":"moʻui: {n} ʻoku sio","live.watching.other":"moʻui: {n} ʻoku sio","live.last.now":"Naʻe ʻosi pē hono ʻave ʻa e kaati fakaʻosi","live.last.min.one":"Naʻe ʻave ʻa e kaati fakaʻosi miniti ʻe {n} kuo hili","live.last.min.other":"Naʻe ʻave ʻa e kaati fakaʻosi miniti ʻe {n} kuo hili","live.last.hour.one":"Naʻe ʻave ʻa e kaati fakaʻosi houa ʻe {n} kuo hili","live.last.hour.other":"Naʻe ʻave ʻa e kaati fakaʻosi houa ʻe {n} kuo hili","live.last.day.one":"Naʻe ʻave ʻa e kaati fakaʻosi ʻaho ʻe {n} kuo hili","live.last.day.other":"Naʻe ʻave ʻa e kaati fakaʻosi ʻaho ʻe {n} kuo hili","live.offline":"'Oku mālōlō si'i e palaoti mo'ui. Foki mai 'i he vave.","live.cols":"Backlog|Ke fai|ʻOku fakahoko|Sivi ʻe he kautaha|Maʻau ke test|Maʻá e kautaha|Kuo fai"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Lopoti.","Tuku."]},{"n":2,"texts":["Kanban lopoti.","ʻEiseniti faʻu.","Fakakaukau, faʻu."]},{"n":3,"texts":["Kanban maʻa lopoti.","Fakakaukau hoko moʻoni.","Kanban ʻeiseniti taʻetotongi."]},{"n":5,"texts":["Laupapa kanban ʻoku ngāue ʻeiseniti.","Tohi kaati. ʻEiseniti te nau faʻu.","Taʻetotongi, ʻi he komipiuta, kuo sivi."]},{"n":8,"texts":["Laupapa kanban taʻetotongi ʻoku ngāue ai ʻeiseniti AI.","Tohi ha fakakaukau. ʻEiseniti te nau faʻu. Te ke tali.","Agile maʻa ha tangata mo e lopoti kātaki."]},{"n":13,"texts":["Laupapa kanban ʻi hoʻo komipiuta ʻoku toʻo ai ʻe he ʻeiseniti AI ʻa e kaati.","Tohi ha fakakaukau. Te nau faʻu ia, pea te ne siviʻi ʻe ha sivi.","Taʻetotongi, ʻikai ha akaunití: ko ha laupapa, ngaahi lopoti, pea ko koe ʻoku takí."]},{"n":21,"texts":["Ko e AI-gile ko ha laupapa kanban ia ki he ngāue mo e ʻeiseniti AI. ʻOku nau toʻo e kaati; te ke sivi mo tali.","Ko e poloseki kotoa ʻoku ʻi ai ha taki mo ha kautaha ʻeiseniti AI. Fakahā ʻi ha kaati pea ʻoku ngāue ʻa e kautaha.","Ko ha laupapa fakafoʻituitui taʻetotongi ʻoku ngāue ʻi hoʻo komipiuta. Ko e kau ngāue ko e lopoti. Ko koe ʻoku pehē ʻio."]},{"n":34,"texts":["Tuku e fakakaukau ki ha laupapa. Ko e kautaha ʻeiseniti AI ʻoku liliu ia ki he meʻa ʻoku ngāue, sivi ia, pea foki mai mo e sitepu. ʻIkai ha meʻa kuo fai kae ʻoua ke ke pehē.","Ko e AI-gile ko ha laupapa kanban naʻe faʻu ʻe Rich mo e tokoni lahi mei he ngaahi ʻeiseniti. ʻOku taʻetotongi, ngāue ʻi hoʻo komipiuta, pea vahevahe mo e kaungāmeʻa, ʻikai fakatau atu.","Fakakaukauʻi ha laupapa kanban angamaheni, mei he Backlog ki he Kuo fai, ka ko e ʻeiseniti AI ʻoku toʻo e kaati. ʻOku nau fakahā e fakalakalaka, fehuʻi ʻo ka tuʻu, pea tatali ki hoʻo tali."]},{"n":55,"texts":["Ko e AI-gile ko ha laupapa kanban ʻa ia ko e kautaha ko e ʻeiseniti AI. Ko e poloseki kotoa ʻoku ʻi ai ha taki ʻoku palani mo ha kau tokoni ʻoku faʻu. ʻO ka mateuteu, ʻoku sivi ʻe ha sivi AI pea tā ha screenshot, pea hoko ia ki hoʻo haʻanga. Tali ia, pe fakahā pea nau toe fai.","Naʻe kamata ia ko e founga ʻa ha tokotaha ke muimui ki he ngaahi seti AI lahi taha, pea tupu ko ha laupapa totonu. ʻOku ngāue ʻi hoʻo komipiuta, ʻikai fiemaʻu ha akaunití, ʻikai ha toʻo fakaʻilonga. ʻOku taʻetotongi maʻa e kaungāmeʻa. ʻOku kei teʻeki kakato, ko ia ʻamanaki ki ha fakaofo.","ʻOku ʻeni ʻa e tala moʻoni. Kei fiemaʻu ke ke ʻai e ngaahi fakakaukau, pea sivi e ola. Ko e AI-gile ʻoku ne fai e meʻa kotoa ʻi he vahaʻa: tauhi e kaati, ʻā ʻa e ʻeiseniti totonu, fakahā e meʻa kuo liliu, pea tānaki ia ki ha haʻanga nounou maʻau."]},{"n":89,"texts":["Ko e AI-gile ko ha laupapa kanban taʻetotongi ʻokú ke fakahoko ʻi hoʻo komipiuta. ʻI he feituʻu ʻo e kakai, ko e poloseki kotoa ʻoku ʻi ai ha kautaha ʻeiseniti AI: ha taki ʻoku liliu hoʻo fakakaukau ki he kaati mo ha palani, mo e kau tokoni ʻoku toʻo e kaati. ʻO ka faʻu ha meʻa, ʻoku muimui ha sivi AI ki he sitepu pea fakahā kiate koe. Pea tatali ia ʻi ha haʻanga ʻoku ui ko e Maʻau. Tali ia, pe fakahā pea feinga e kautaha ʻo toe. ʻIkai ha meʻa te ne aʻu ki he Kuo fai ʻikai ko koe.","Ko ha ngaahi meʻa ʻe ʻikai te ke ʻamanaki. ʻOku fakafonu ʻe ha leʻo poʻuli ʻa e kolomu Ke fai lolotonga hoʻo mohe, ʻo fili e kaati ʻikai fiemaʻu ha tali meiate koe. ʻOku fakahā ʻe ha tokeni lau ʻa e meʻa kuo ngāueʻaki ʻe he ʻeiseniti, pea tala ʻe he No Token Mode ke tuku e fakamoleki. ʻE lava ke ke fekau pōpoaki ki he kaungāmeʻa, pea ʻoku fakapulipuliʻi mei he ʻuluaki ki he ngataʻanga. ʻOku lea e laupapa ʻi he lea ʻe 120, kau ai e Hōlani, kaniva mo e Klingon. ʻIkai ha totongi, pea ʻikai ha taha ʻoku fakatau atu ha meʻa kiate koe.","Ko e AI-gile ko ha kiʻi poloseki fakafoʻituitui, ʻikai ko ha kautaha. Naʻe fie tauhi ʻe Rich ha ngaahi poloseki AI ʻo ʻikai fakaava e polokalama kotoa, ko ia naʻá ne mo e ʻeiseniti naʻa nau faʻu ha laupapa, pea ngāueʻaki ia ke faʻu e toenga ʻo ia pē. ʻOku ʻi he pre-alpha tāpuni, ʻa ia ʻoku ne ngāue, ʻi he lahi taha, maʻa ha kiʻi kaungāmeʻa. ʻIkai ha pēsi totongi, ʻikai ha nusipepa, ʻikai ha palani tupu. Kapau ʻoku ongo ʻaonga, kole ke feinga ʻo ka toe ava siʻi."]},{"n":144,"texts":["Ko e AI-gile ko ha laupapa kanban maʻa ha tangata pe taha mo e ʻeiseniti AI lahi. ʻOku ngāue ʻi hoʻo komipiuta pea taʻetotongi kakato. ʻOku ke tānaki ha ngaahi poloseki, pea ko e poloseki taki taha ʻoku maʻu ha taki mo ha kiʻi kautaha. ʻOku ke talanoa mo e taki, hangē ko e Discord, pea fakamatala ha fakakaukau; ʻoku liliu ia ʻe he taki ki he kaati mo ha palani, pea tatali kae lomiʻi ʻe koe ʻa e Ō. ʻOku ngāue ʻa e kautaha ʻi he kaati ʻo muimui ki he mahuʻinga, ʻaki ha meʻangāue laine fekau faingofua. Ki muʻa ke foki mai ha meʻa, ʻoku muimui ha sivi AI ki he sitepu ʻi ha kopi ʻo e polokalama pea fakataha ha screenshot. Ko e ngāue kuo kakato ʻoku hoko ki hoʻo haʻanga mo e faile kuo liliu. Tali ia, pe tuku ha fakamatala pea feinga ʻa e kautaha. Ko koe pē te ne lava ʻo hiki ha kaati ki he Kuo fai.","Ko ha ʻaho mo e AI-gile, ʻi he fakafuofua. ʻI he efiafi ʻokú ke tuku ha ngaahi fakamatala siʻi: ko e pātani ni ʻoku hala hono potu, ko e lisi ko ia ke fakahokohoko, ʻe lava nai ha founga fakapoʻuli. ʻOkú ke ʻalu ki he mohe. ʻOku lau ʻe he ʻeiseniti e fakamatala, fai e liliu, sivi ia pea foki mai. Kapau ʻe maha e Ke fai, ʻoku fakafonu ia ʻe he leʻo poʻuli mei he backlog ʻaki e kaati ʻikai fiemaʻu ha tali meiate koe. ʻI he pongipongi ʻoku ʻi ai ha haʻanga nounou pe taha: ha ngaahi fehuʻi siʻi mo ha ngaahi meʻa ke feinga, taki taha mo e sitepu ʻe lava ke muimui ai ha tangata mohe mo ha screenshot. ʻOku ke lomiʻi, tali e lelei pea foki e toenga. ʻOku fakahā ʻe ha tokeni lau e meʻa kuo moleki, pea ʻoku ʻi ai e No Token Mode maʻa e uike fakamālohi. Pea ʻokú ke kai ho pongipongi, ʻa ia ʻoku teʻeki lava ke tokoni ai e ʻeiseniti.","ʻUluaki, ko e meʻa ʻoku ʻikai ko e AI-gile. ʻIkai ko ha kautaha kamata, ʻikai fakatau atu, pea ʻikai ha taha ʻoku tānaki hoʻo fakamatala. Ko ha laupapa taʻetotongi ia ʻoku ngāue ʻi hoʻo komipiuta, ʻikai ha akaunití, ʻikai ha toʻo fakaʻilonga, ʻikai ha kuki. Ko e meʻa ia: ko ha potu pe taha ʻoku maau ke sio ki he poloseki AI kotoa he taimi pē taha, mo ha kautaha ʻeiseniti ʻoku fai e kaati pea ko koe ʻoku fai e fili. ʻOku ne fakataha e kaati fekauʻaki, fakatonutonu e ʻulu hala, pea sio ki he maʻama ʻo e kouti. ʻOku lea ʻi he lea ʻe 120, mei he Hōlani ki he kaniva mo e Klingon. ʻE lava ʻe he kaungāmeʻa ʻo fekau pōpoaki fakapulipuli. Naʻe faʻu ia ʻe Rich mo ha tokolahi ʻo e ʻeiseniti kātaki, ʻaki hono ngāueʻaki ʻa ia pē. ʻOku ʻi he pre-alpha tāpuni, ko ia ʻoku matolu ʻi ha ngaahi potu. Kapau ʻoku fakafiefia, kole fakaʻapaʻapa pea te ke lava ʻo hū vave."]}],"quips":{"1":"Lea pe taha. Toʻa. Mahalo he toʻa tōnunu.","3":"Lea ʻe tolu. Kuo moʻoni ange ia he lahi taha ʻo e peesi ʻo e koloa.","8":"Lea ʻe valu. Kei nounou ange ia he stand-up.","21":"Ko e lōloa ko e story points, ʻo kapau. ʻIo ʻoku pehē.","55":"Lea ʻe nimangofulu-mā-nima. Naʻe kakato ha kaati ʻe ua lolotonga hoʻo lau ʻeni.","144":"Ko e taha lōloa ia. ʻIkai ha 233. Kuo ʻalu e ʻeiseniti ki he mohe."}},"timeline":{"first-idea.name":"Ko e fakakaukau ʻuluaki","first-idea.line":"Ko e talanoa ʻuluaki pē, ki muʻa ke ʻi ai ha kouti.","first-board.name":"Laupapa ʻuluaki","first-board.line":"Ko ha laupapa ʻoku muimui ki hono faʻu ʻo ia: ngaahi kaati, kolomu, toho mo tuku, ngaahi poloseki.","team-roles.name":"Kautaha mo e ngaahi fatongia","team-roles.line":"Ngaahi tohi ʻo e ʻeiseniti, ngaahi sīpinga kautaha, ngaahi potu mo e tokotaha ʻoku fai ʻa e hā.","install.name":"Fokotuʻu mo e ngaahi tuku atu","install.line":"Ko ha zip ʻe lava ke fokotuʻu ʻe ha kaungāmeʻa, fakafoʻou ʻe ia pē, ngaahi hala mo e foki ki mui.","usage-saver.name":"Fakamoleki siʻi","usage-saver.line":"Fua ʻa e totongi ʻo e ngaahi fakahoko, tauhi ʻa e kouti ke maʻama, fakamoleki siʻi hoʻo fakangatangata.","friends.name":"Ngaahi kaungāmeʻa mo e vahevahe","friends.line":"Ngaahi pōpoaki fakapulipuli, relay fakapulipuliʻi, ngaahi fakaafe, ngaahi fatongia mo e ngaahi poloseki vahevahe.","languages.name":"Ngaahi lea","languages.line":"Ko e tohi kotoa ʻo e screen ʻi ha faile lea, mo e lea faka-Hōlani mo e faka-Felemisi ʻuluaki.","ai-tester.name":"Sivi AI","ai-tester.line":"ʻOku sivi ʻuluaki ʻe he sivi ʻa e tuku atu kotoa pea fakahā ʻa e meʻa naʻá ne sio ki ai.","website.name":"Uepisaiti","website.line":"aigile.lol, ko e fanga kiʻi fakamatala mo e laine taimi ni.","streaming.name":"Talanoa mo e streaming","streaming.line":"Discord, Twitch, OBS, founga streamer, ngaahi GIF mo e ngaahi emoji.","no-ai.name":"Tohi ʻikai ha AI","no-ai.line":"Ko ha laupapa maʻa e kakai ʻoku nau tohi kouti ʻikai ha AI, mo e ngaahi laupapa fakamaʻuʻanga.","night-watch.name":"Leʻo poʻuli","night-watch.line":"Ko ha leʻo mo e Scrum Master ʻoku nau tauhi ʻa e ngaahi kautaha ʻi he ngāue lolotonga hoʻo mohe.","p-more.name":"Meʻa kotoa pē kehe","p-more.line":"Ngaahi fakakaukau siʻi ʻoku kei tatali ki honau taimi.","p-android.name":"Telefoni mo e Android","p-android.line":"Aʻu ki hoʻo laupapa mei he telefoni, pea hoko ko e polokalama Android moʻoni.","p-release.name":"Alpha mo e hili ia","p-release.line":"Alpha tāpuni, ko e saiti moʻui, pea beta.","p-languages.name":"Ngaahi lea lahi ange","p-languages.line":"Lea ʻe laka hake he teau, mo ha founga immersion maʻa e kakai ako lea.","p-engines.name":"Ngaahi mīsini AI lahi ange","p-engines.line":"Fili ʻa e Claude, Codex pe Gemini maʻa e ʻeiseniti taki taha.","p-pro.name":"Founga fakapolofesinale","p-pro.line":"Ngaahi fakaʻilonga fakatuʻutāmaki, ngaahi matapā fakataha, ngaahi kaati hoko mo e ngaahi pā fakatauhi.","p-self.name":"Tokangaʻi koe","p-self.line":"Founga ongosia, ngaahi fakamanatu tokangaʻi kita mo e 4:20.","p-servers.name":"Ngaahi sēvā mo e tupu","p-servers.line":"Ngaahi seti ʻo e sēvā fakamāmani, ngaahi fatongia mo e palani ki he tupu.","p-livestream.name":"Ngaahi tānaki streaming","p-livestream.line":"Talanoa Twitch, ngaahi emoji fakafiemālie mo ha sio moʻui maʻa e kakai kotoa."},"words":{"button":"📖 Ngaahi lea polokalama","h":"📖 Ngaahi lea polokalama fakamatala","intro":"Ko e ngaahi lea ʻoku ngāueʻaki ʻe he kau tohi polokalama (mo e ngaahi kautaha AI), ʻi he lea faingofua.","search":"Kumi ha lea…","none":"ʻIkai ha lea ʻoku tatau.","close":"Tāpuni","list":[{"id":"backlog","word":"Backlog","text":"Ngaahi fakakaukau mo e ngāue te'eki palani. ʻIkai ha me'a ʻe fai ai kae ʻoua ke ʻave ki he Ke fai."},{"id":"sprint","word":"Sprint","text":"Ko ha vaha'a ngāue nounou (ʻuhinga ko ha uike pe ua) mo ha ngaahi kaati kuo loto taha ke fakaʻosi.","also":["sprints"]},{"id":"standup","word":"Stand-up","text":"Ko ha fetuʻutaki vave: ko e hā naʻe fai ʻe he mēmipa taki taha, ko e hā ʻe fai hoko, pea ko e hā ʻoku taʻofi ai.","also":["standup","stand-ups"]},{"id":"bug","word":"Bug","text":"Ko ha me'a ʻoku ʻikai ngāue ʻo hangē ko e meʻa ʻoku totonu ke ngāue ai.","also":["bugs"]},{"id":"test","word":"Test","text":"Feinga ki ha konga ngāue kuo ʻosi ke sivi pe ʻoku fai ʻa e me'a naʻe kole, kimuʻa pea ke fakamoʻoni.","also":["tests"],"noTip":1},{"id":"commit","word":"Commit","text":"Ko ha tā kuo tauhi ʻo e koti, mo ha fakamatala nounou ʻo e me'a naʻe liliu. Te ke lava maʻu pē ʻo foki ki ha taha.","also":["commits"]},{"id":"push","word":"Push","text":"Fekau e ngaahi tā kuo tauhi (commits) mei he komipiuta ni ki he GitHub, ke tauhi mo vahevahe."},{"id":"branch","word":"Branch","text":"Ko ha laine ngāue kehe ʻi he koti, ke lava ʻo fai ha ngaahi liliu taʻe ala ki he paaki tefito.","also":["branches"]},{"id":"merge","word":"Merge","text":"Fakatahaʻi e ngaahi liliu ʻo ha branch ki he paaki tefito."},{"id":"repo","word":"Repo","text":"Ko e folda ʻo e poloseki ʻo e koti mo hono hisitōlia kakato ʻo e ngaahi commit, ʻoku fa'a tauhi foki ʻi he GitHub.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"Fakama'a e koti taʻe liliu e me'a ʻoku ne fai: ngaahi fail siʻi ange, ngaahi hingoa mahino ange, siʻi ange ʻa e toe fakahoko."},{"id":"deploy","word":"Deploy","text":"Fokotuʻu ha paaki foʻou ke moʻui, hangē ko ha sēvā ʻoku ngāueʻaki ai ʻe he kakai."},{"id":"kanban","word":"Kanban","text":"Ko ha laupapa mo e ngaahi kolomu (Ke fai, ʻOku fakahoko, Kuo fai) ʻoku ʻalu ai e ngaahi kaati mei toʻohema ki toʻomataʻu ʻi he taimi ʻoku fai ai e ngāue."},{"id":"wip","word":"WIP limit","text":"Ngāue ʻoku fakahoko: ko e lahi taha ʻo e ngaahi kaati ʻe lava ke hao ʻi ha kolomu, ke fakaʻosi ʻe he kautaha e ngaahi me'a kimuʻa pea kamata ha toe.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Kole ke vakaiʻi mo fakatahaʻi ʻa e ngaahi liliu ʻo ha branch ki he paaki tefito.","also":["PR"]},{"id":"hook","word":"Hook","text":"Ko ha fekau siʻisiʻi ʻoku lele ʻiate ia ʻi ha taimi kuo fokotuʻu, hangē ko e ʻi he kamata ʻa ha sēsini AI, ke fanongo ʻa e kautaha ki hoʻo ngaahi fakamatala.","also":["hooks"]},{"id":"token","word":"Token","text":"Ko e iuniti ʻoku lau ai e ngāueʻaki AI: ʻuhinga ko ha mataʻitohi siʻi ʻo e tohi kuo lau pe tohi. Token siʻi ange, palani lahi ange ʻoku toe.","also":["tokens"]},{"id":"agent","word":"Agent","text":"Ko ha AI ʻoku ngāue ʻiate ia ki ha ngāue: lau e koti, fai ha liliu, lele ha ngaahi sivi, pea lipooti mai.","also":["agents"]}]}};
